ALTER TABLE "payment_attempts" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE POLICY "payment_attempt_read" ON "payment_attempts" AS PERMISSIVE FOR SELECT TO public USING ((current_setting('rove.actor_role',true)='rider' AND EXISTS(SELECT 1 FROM public.rides r JOIN public.users u ON u.id=r.rider_id WHERE r.id="payment_attempts"."ride_id" AND r.rider_id=NULLIF(current_setting('rove.actor_id',true),'')::uuid AND u.role='rider' AND u.disabled=false)) OR (("payment_attempts"."source"=NULLIF(current_setting('rove.payment_attempt_read',true),'')::jsonb->>'source' AND ("payment_attempts"."id"=(NULLIF(current_setting('rove.payment_attempt_read',true),'')::jsonb->>'attemptId')::uuid OR "payment_attempts"."ride_id"=(NULLIF(current_setting('rove.payment_attempt_read',true),'')::jsonb->>'rideId')::uuid OR "payment_attempts"."intent_id"=NULLIF(current_setting('rove.payment_attempt_read',true),'')::jsonb->>'intentId')) OR (NULLIF(current_setting('rove.payment_attempt_read',true),'')::jsonb->>'kind'='ride-event' AND "payment_attempts"."ride_id"=(NULLIF(current_setting('rove.payment_attempt_read',true),'')::jsonb->>'rideId')::uuid) OR "payment_attempts"."source"=NULLIF(current_setting('rove.payment_attempt_scan',true),'') OR "payment_attempts"."id"=NULLIF(current_setting('rove.payment_attempt_lock',true),'')::uuid) OR (current_setting('rove.actor_role',true)='staff' AND current_setting('rove.actor_mfa',true)='true' AND EXISTS(SELECT 1 FROM public.users u JOIN public.staff_permissions p ON p.staff_id=u.id WHERE u.id=NULLIF(current_setting('rove.actor_id',true),'')::uuid AND u.role='staff' AND u.disabled=false AND p.permission='privacy.close') AND EXISTS(SELECT 1 FROM public.rides r WHERE r.id="payment_attempts"."ride_id" AND (r.rider_id=NULLIF(current_setting('rove.payment_attempt_closure',true),'')::uuid OR r.driver_id=NULLIF(current_setting('rove.payment_attempt_closure',true),'')::uuid))));--> statement-breakpoint
CREATE POLICY "payment_attempt_lock" ON "payment_attempts" AS PERMISSIVE FOR UPDATE TO public USING (((current_setting('rove.actor_role',true)='rider' AND EXISTS(SELECT 1 FROM public.rides r JOIN public.users u ON u.id=r.rider_id WHERE r.id="payment_attempts"."ride_id" AND r.rider_id=NULLIF(current_setting('rove.actor_id',true),'')::uuid AND u.role='rider' AND u.disabled=false)) OR (("payment_attempts"."source"=NULLIF(current_setting('rove.payment_attempt_read',true),'')::jsonb->>'source' AND ("payment_attempts"."id"=(NULLIF(current_setting('rove.payment_attempt_read',true),'')::jsonb->>'attemptId')::uuid OR "payment_attempts"."ride_id"=(NULLIF(current_setting('rove.payment_attempt_read',true),'')::jsonb->>'rideId')::uuid OR "payment_attempts"."intent_id"=NULLIF(current_setting('rove.payment_attempt_read',true),'')::jsonb->>'intentId')) OR (NULLIF(current_setting('rove.payment_attempt_read',true),'')::jsonb->>'kind'='ride-event' AND "payment_attempts"."ride_id"=(NULLIF(current_setting('rove.payment_attempt_read',true),'')::jsonb->>'rideId')::uuid) OR "payment_attempts"."source"=NULLIF(current_setting('rove.payment_attempt_scan',true),'') OR "payment_attempts"."id"=NULLIF(current_setting('rove.payment_attempt_lock',true),'')::uuid) OR (current_setting('rove.actor_role',true)='staff' AND current_setting('rove.actor_mfa',true)='true' AND EXISTS(SELECT 1 FROM public.users u JOIN public.staff_permissions p ON p.staff_id=u.id WHERE u.id=NULLIF(current_setting('rove.actor_id',true),'')::uuid AND u.role='staff' AND u.disabled=false AND p.permission='privacy.close') AND EXISTS(SELECT 1 FROM public.rides r WHERE r.id="payment_attempts"."ride_id" AND (r.rider_id=NULLIF(current_setting('rove.payment_attempt_closure',true),'')::uuid OR r.driver_id=NULLIF(current_setting('rove.payment_attempt_closure',true),'')::uuid)))) AND NULLIF(current_setting('rove.payment_attempt_write',true),'')::jsonb IS NULL) WITH CHECK (false);--> statement-breakpoint
CREATE POLICY "payment_attempt_insert" ON "payment_attempts" AS PERMISSIVE FOR INSERT TO public WITH CHECK (current_setting('rove.actor_role',true)='rider' AND EXISTS(SELECT 1 FROM public.rides r JOIN public.users u ON u.id=r.rider_id WHERE r.id="payment_attempts"."ride_id" AND r.rider_id=NULLIF(current_setting('rove.actor_id',true),'')::uuid AND u.role='rider' AND u.disabled=false) AND "payment_attempts"."intent_id" IS NULL AND "payment_attempts"."revision"=0 AND "payment_attempts"."provider_status" IS NULL AND "payment_attempts"."reconciled_at" IS NULL AND EXISTS(SELECT 1 FROM public.rides r JOIN public.payment_customers c ON c.rider_id=r.rider_id WHERE r.id="payment_attempts"."ride_id" AND r.state='searching' AND c.id="payment_attempts"."customer_binding_id" AND c.source="payment_attempts"."source" AND c.customer_id IS NOT NULL AND r.fare_cents="payment_attempts"."amount_cents"));--> statement-breakpoint
CREATE POLICY "payment_attempt_result" ON "payment_attempts" AS PERMISSIVE FOR UPDATE TO public USING (jsonb_build_object('attemptId',"payment_attempts"."id",'rideId',"payment_attempts"."ride_id",'bindingId',"payment_attempts"."customer_binding_id",'source',"payment_attempts"."source",'amountCents',"payment_attempts"."amount_cents")=(NULLIF(current_setting('rove.payment_attempt_write',true),'')::jsonb-'intentId') AND ("payment_attempts"."intent_id" IS NULL OR "payment_attempts"."intent_id"=NULLIF(current_setting('rove.payment_attempt_write',true),'')::jsonb->>'intentId')) WITH CHECK (jsonb_build_object('attemptId',"payment_attempts"."id",'rideId',"payment_attempts"."ride_id",'bindingId',"payment_attempts"."customer_binding_id",'source',"payment_attempts"."source",'amountCents',"payment_attempts"."amount_cents")=(NULLIF(current_setting('rove.payment_attempt_write',true),'')::jsonb-'intentId') AND "payment_attempts"."intent_id"=NULLIF(current_setting('rove.payment_attempt_write',true),'')::jsonb->>'intentId');
--> statement-breakpoint
ALTER TABLE payment_attempts FORCE ROW LEVEL SECURITY;
